{"rob":"robolang 1.3;

task handover(robot amr, robot arm, object p, location src, location mid, location dst) {
    goal { object_at p dst; }
    plan {
        move amr to src;
        grasp amr p;
        move amr to mid;
        place amr p at mid;
        move arm to mid;
        grasp arm p;
        move arm to dst;
        place arm p at dst;
    }
}
